styles:
#customSpinnerBtn::part(spinner) svg {
            stroke: #ff6b6b;
            stroke-width: 3;
          }
          #customSpinnerBtn::part(spinner) svg circle {
            stroke-dasharray: 12 6;
          }

blocks.code:
/* afecta solo cuando está loading */
iswc-button:state(loading) {
  --iswc-button-border-radius: 999px;
}

/* afecta solo cuando es link */
iswc-button:state(link)::part(button) {
  text-decoration: underline;
}

/* afecta solo cuando es icon-only */
iswc-button:state(icon-button) {
  --_hpad: 0;
}
